#include <algorithm>
#include <array>
#include <cstdlib>
#include <iostream>
#include <numeric>
#include <sstream>
#include <stdexcept>
#include <string>
#include <utility>
#include <vector>

struct Rational {
  long long numerator{0};
  long long denominator{1};

  Rational() = default;
  Rational(long long num, long long den = 1) : numerator(num), denominator(den) {
    if (denominator == 0) {
      throw std::invalid_argument("zero rational denominator");
    }
    if (denominator < 0) {
      numerator = -numerator;
      denominator = -denominator;
    }
    const auto divisor = std::gcd(std::llabs(numerator), denominator);
    numerator /= divisor;
    denominator /= divisor;
  }
};

Rational operator+(const Rational &left, const Rational &right) {
  return {left.numerator * right.denominator + right.numerator * left.denominator,
          left.denominator * right.denominator};
}

Rational operator-(const Rational &left, const Rational &right) {
  return {left.numerator * right.denominator - right.numerator * left.denominator,
          left.denominator * right.denominator};
}

Rational operator-(const Rational &value) { return {-value.numerator, value.denominator}; }

Rational operator*(const Rational &left, const Rational &right) {
  return {left.numerator * right.numerator, left.denominator * right.denominator};
}

bool operator==(const Rational &left, const Rational &right) {
  return left.numerator == right.numerator && left.denominator == right.denominator;
}

bool operator<=(const Rational &left, const Rational &right) {
  return left.numerator * right.denominator <= right.numerator * left.denominator;
}

Rational absolute(const Rational &value) {
  return {std::llabs(value.numerator), value.denominator};
}

using Vector = std::array<Rational, 3>;

Rational dot(const Vector &left, const Vector &right) {
  Rational result;
  for (std::size_t coordinate = 0; coordinate < 3; ++coordinate) {
    result = result + left[coordinate] * right[coordinate];
  }
  return result;
}

Vector add(const Vector &left, const Vector &right) {
  return {left[0] + right[0], left[1] + right[1], left[2] + right[2]};
}

Vector subtract(const Vector &left, const Vector &right) {
  return {left[0] - right[0], left[1] - right[1], left[2] - right[2]};
}

Vector negate(const Vector &value) { return {-value[0], -value[1], -value[2]}; }

Vector cross(const Vector &left, const Vector &right) {
  return {left[1] * right[2] - left[2] * right[1],
          left[2] * right[0] - left[0] * right[2],
          left[0] * right[1] - left[1] * right[0]};
}

bool is_zero(const Vector &value) {
  return std::all_of(value.begin(), value.end(), [](const Rational &coordinate) {
    return coordinate.numerator == 0;
  });
}

bool equal_vector(const Vector &left, const Vector &right) {
  return std::equal(left.begin(), left.end(), right.begin());
}

bool exact_pair_compatible(const Vector &left, const Vector &right) {
  const Rational plus_squared = dot(add(left, right), add(left, right));
  const Rational minus_squared = dot(subtract(left, right), subtract(left, right));
  const Rational squared_sum = plus_squared + minus_squared;
  const Rational remainder = Rational(4) - squared_sum;
  return squared_sum <= Rational(4) && Rational(4) * plus_squared * minus_squared <= remainder * remainder;
}

bool exact_pair_boundary(const Vector &left, const Vector &right) {
  const Rational plus_squared = dot(add(left, right), add(left, right));
  const Rational minus_squared = dot(subtract(left, right), subtract(left, right));
  const Rational squared_sum = plus_squared + minus_squared;
  const Rational remainder = Rational(4) - squared_sum;
  return squared_sum <= Rational(4) && Rational(4) * plus_squared * minus_squared == remainder * remainder;
}

Rational parse_rational(const std::string &text) {
  const auto slash = text.find('/');
  if (slash == std::string::npos) {
    return {std::stoll(text)};
  }
  return {std::stoll(text.substr(0, slash)), std::stoll(text.substr(slash + 1))};
}

Vector parse_vector(const std::string &text) {
  std::stringstream stream(text);
  std::string part;
  Vector result;
  std::size_t index = 0;
  while (std::getline(stream, part, ',')) {
    if (index >= result.size()) {
      throw std::invalid_argument("too many vector coordinates");
    }
    result[index++] = parse_rational(part);
  }
  if (index != result.size()) {
    throw std::invalid_argument("a Bloch vector needs three coordinates");
  }
  return result;
}

std::vector<Vector> parse_vectors(const std::string &text) {
  std::stringstream stream(text);
  std::string part;
  std::vector<Vector> result;
  while (std::getline(stream, part, '|')) {
    result.push_back(parse_vector(part));
  }
  return result;
}

void print_rational(const Rational &value) {
  std::cout << ',' << value.numerator << ',' << value.denominator;
}

int main() {
  std::cout << "row_index,measurement_count,pair_count,zero_bloch_vector_count,sharp_measurement_count,"
               "commuting_pair_count,orthogonal_pair_count,duplicate_measurement_pair_count,"
               "antipodal_measurement_pair_count,compatible_pair_count,incompatible_pair_count,"
               "boundary_pair_count,sum_sharpness_squared_num,sum_sharpness_squared_den,"
               "frame_potential_num,frame_potential_den\n";
  std::string line;
  while (std::getline(std::cin, line)) {
    if (line.empty()) {
      continue;
    }
    const auto separator = line.find(';');
    if (separator == std::string::npos) {
      throw std::invalid_argument("missing row separator");
    }
    const auto row_index = std::stoll(line.substr(0, separator));
    const auto vectors = parse_vectors(line.substr(separator + 1));
    long long zero_count = 0;
    long long sharp_count = 0;
    long long commuting_count = 0;
    long long orthogonal_count = 0;
    long long duplicate_count = 0;
    long long antipodal_count = 0;
    long long compatible_count = 0;
    long long boundary_count = 0;
    Rational sum_norm_squared;
    Rational frame_potential;

    for (const auto &left : vectors) {
      const auto norm_squared = dot(left, left);
      sum_norm_squared = sum_norm_squared + norm_squared;
      zero_count += is_zero(left);
      sharp_count += norm_squared == Rational(1);
      for (const auto &right : vectors) {
        const auto inner_product = dot(left, right);
        frame_potential = frame_potential + inner_product * inner_product;
      }
    }
    for (std::size_t left_index = 0; left_index < vectors.size(); ++left_index) {
      for (std::size_t right_index = left_index + 1; right_index < vectors.size(); ++right_index) {
        const auto &left = vectors[left_index];
        const auto &right = vectors[right_index];
        commuting_count += is_zero(cross(left, right));
        orthogonal_count += dot(left, right) == Rational();
        duplicate_count += equal_vector(left, right);
        antipodal_count += !is_zero(left) && equal_vector(left, negate(right));
        compatible_count += exact_pair_compatible(left, right);
        boundary_count += exact_pair_boundary(left, right);
      }
    }
    const auto pair_count = static_cast<long long>(vectors.size() * (vectors.size() - 1) / 2);
    std::cout << row_index << ',' << vectors.size() << ',' << pair_count << ',' << zero_count << ','
              << sharp_count << ',' << commuting_count << ',' << orthogonal_count << ',' << duplicate_count
              << ',' << antipodal_count << ',' << compatible_count << ',' << pair_count - compatible_count
              << ',' << boundary_count;
    print_rational(sum_norm_squared);
    print_rational(frame_potential);
    std::cout << '\n';
  }
  return 0;
}

